<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Box, ChatDotRound, Delete, Edit, Plus, Promotion, Search } from '@element-plus/icons-vue'
import { apiMessage, blogApi } from '@blog/api'
import { formatDate, statusLabel } from '@blog/format'
import type { Category, Post, PostPage } from '@blog/types'
const loading = ref(false); const page = ref<PostPage>({ items: [], total: 0, page: 1, pageSize: 20 }); const categories = ref<Category[]>([]); const filters = reactive({ q: '', status: '', categoryId: '', page: 1, pageSize: 20 })
async function load() { loading.value = true; try { page.value = await blogApi.posts(filters) } catch (error) { ElMessage.error(apiMessage(error, '文章列表加载失败')) } finally { loading.value = false } }
async function publish(post: Post) { try { await ElMessageBox.confirm(`确认发布《${post.title}》？`, '发布文章', { type: 'warning' }); await blogApi.publishPost(post.id); ElMessage.success('文章已发布'); await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(apiMessage(error, '发布失败')) } }
async function archive(post: Post) { try { const current = await blogApi.post(post.id); await blogApi.updatePost(post.id, { ...current, status: 'archived' }); ElMessage.success('文章已归档'); await load() } catch (error) { ElMessage.error(apiMessage(error, '归档失败')) } }
async function remove(post: Post) { try { await ElMessageBox.confirm(`确认删除《${post.title}》？`, '删除文章', { type: 'warning' }); await blogApi.deletePost(post.id); ElMessage.success('文章已删除'); await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(apiMessage(error, '删除失败')) } }
onMounted(async () => { try { categories.value = await blogApi.categories() } catch { categories.value = [] }; await load() })
</script>
<template><div class="management-page blog-page"><div class="toolbar"><div class="filters blog-post-filters"><el-input v-model="filters.q" :prefix-icon="Search" clearable placeholder="搜索标题或正文" @keyup.enter="filters.page = 1; load()" /><el-select v-model="filters.status" clearable placeholder="全部状态" @change="filters.page = 1; load()"><el-option label="草稿" value="draft" /><el-option label="已发布" value="published" /><el-option label="已归档" value="archived" /></el-select><el-select v-model="filters.categoryId" clearable placeholder="全部分类" @change="filters.page = 1; load()"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-tooltip content="刷新"><el-button :icon="Search" aria-label="刷新" @click="load" /></el-tooltip></div><el-button type="primary" :icon="Plus" @click="$router.push('/blog/posts/new')">写文章</el-button></div><div class="table-panel"><el-table v-loading="loading" :data="page.items" empty-text="还没有文章"><el-table-column label="文章" min-width="300"><template #default="scope"><div class="primary-cell"><strong>{{ scope.row.title }}</strong><small>{{ scope.row.slug }} · {{ formatDate(scope.row.updatedAt) }}</small><span class="blog-tag-list"><el-tag v-for="tag in scope.row.tags" :key="tag" size="small" type="info" effect="plain">{{ tag }}</el-tag></span></div></template></el-table-column><el-table-column label="分类" width="120"><template #default="scope">{{ scope.row.category?.name || '未分类' }}</template></el-table-column><el-table-column prop="authorName" label="作者" width="110" /><el-table-column label="评论" width="80"><template #default="scope"><el-button link :icon="ChatDotRound" @click="$router.push({ path: '/blog/comments', query: { postId: scope.row.id } })">{{ scope.row.commentCount }}</el-button></template></el-table-column><el-table-column label="状态" width="100"><template #default="scope"><el-tag :type="scope.row.status === 'published' ? 'success' : scope.row.status === 'archived' ? 'info' : 'warning'" effect="plain">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="175" fixed="right"><template #default="scope"><div class="row-actions"><el-tooltip content="编辑"><el-button text :icon="Edit" aria-label="编辑" @click="$router.push(`/blog/posts/${scope.row.id}/edit`)" /></el-tooltip><el-tooltip v-if="scope.row.status !== 'published'" content="发布"><el-button text type="success" :icon="Promotion" aria-label="发布" @click="publish(scope.row)" /></el-tooltip><el-tooltip v-if="scope.row.status !== 'archived'" content="归档"><el-button text :icon="Box" aria-label="归档" @click="archive(scope.row)" /></el-tooltip><el-tooltip content="删除"><el-button text type="danger" :icon="Delete" aria-label="删除" @click="remove(scope.row)" /></el-tooltip></div></template></el-table-column></el-table><div class="pagination-row"><span>共 {{ page.total }} 篇</span><el-pagination v-model:current-page="filters.page" layout="prev, pager, next" :total="page.total" :page-size="page.pageSize" @current-change="load" /></div></div></div></template>
